// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.List;
import java.util.concurrent.AbstractExecutorService;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

import org.eclipse.rdf4j.sail.lmdb.LmdbDirectAdjacencyCommitDelta.SealedDirectDelta;
import org.junit.jupiter.api.Test;

/** The asynchronous capture: which transactions cross to the capture executor and which seal on the committer. */
class LmdbDirectAdjacencyCommitDeltaCaptureTest {

	/** Queues every task; the test runs them when it chooses. */
	private static final class ManualExecutor extends AbstractExecutorService {
		private final Deque<Runnable> tasks = new ArrayDeque<>();
		private int submitted;

		@Override
		public void execute(Runnable command) {
			submitted++;
			tasks.add(command);
		}

		void runAll() {
			Runnable task;
			while ((task = tasks.poll()) != null) {
				task.run();
			}
		}

		@Override
		public void shutdown() {
		}

		@Override
		public List<Runnable> shutdownNow() {
			return List.of();
		}

		@Override
		public boolean isShutdown() {
			return false;
		}

		@Override
		public boolean isTerminated() {
			return false;
		}

		@Override
		public boolean awaitTermination(long timeout, TimeUnit unit) {
			return true;
		}
	}

	private static LmdbDirectAdjacencyCommitDelta delta(LmdbAdjacencyMemoryAccount account, ManualExecutor executor,
			Runnable beforeCapture) {
		return new LmdbDirectAdjacencyCommitDelta(account, 1L << 30, new AtomicBoolean(), executor, beforeCapture,
				null, () -> account);
	}

	@Test
	void aSmallTransactionSealsOnTheCommittingThreadWithoutTheCaptureExecutor() {
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(1L << 30);
		ManualExecutor executor = new ManualExecutor();
		LmdbDirectAdjacencyCommitDelta delta = delta(account, executor, null);
		delta.begin(1);
		for (int i = 0; i < 3; i++) {
			delta.recordAdd(100 + i, 7, 200 + i, 0, true);
		}

		CompletableFuture<SealedDirectDelta> sealing = delta.sealAsync(2);

		// Sorting three events takes less time than two executor hand-offs: the committer seals its own small
		// transaction, and the commit log sees a sealed record the moment it is staged.
		assertThat(sealing.isDone()).isTrue();
		assertThat(executor.submitted).isZero();
		SealedDirectDelta sealed = sealing.join();
		try {
			assertThat(sealed.revision()).isEqualTo(2);
			assertThat(sealed.pendingTable().rowCount()).isEqualTo(6);
		} finally {
			sealed.close();
		}
		assertThat(account.totalChargedBytes()).isZero();
	}

	@Test
	void aLargeTransactionStillSealsOnTheCaptureExecutor() {
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(1L << 30);
		ManualExecutor executor = new ManualExecutor();
		LmdbDirectAdjacencyCommitDelta delta = delta(account, executor, null);
		delta.begin(1);
		for (int i = 0; i < 600; i++) {
			delta.recordAdd(1_000 + i, 7, 5_000 + i, 0, true);
		}

		CompletableFuture<SealedDirectDelta> sealing = delta.sealAsync(2);

		assertThat(sealing.isDone()).isFalse();
		assertThat(executor.submitted).isPositive();
		executor.runAll();
		assertThat(sealing.isDone()).isTrue();
		SealedDirectDelta sealed = sealing.join();
		try {
			assertThat(sealed.pendingTable().rowCount()).isEqualTo(1_200);
		} finally {
			sealed.close();
		}
		assertThat(account.totalChargedBytes()).isZero();
	}

	@Test
	void aCaptureHookKeepsEvenASmallTransactionOnTheCaptureExecutor() {
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(1L << 30);
		ManualExecutor executor = new ManualExecutor();
		AtomicBoolean hookRan = new AtomicBoolean();
		LmdbDirectAdjacencyCommitDelta delta = delta(account, executor, () -> hookRan.set(true));
		delta.begin(1);
		delta.recordAdd(1, 2, 3, 0, true);

		CompletableFuture<SealedDirectDelta> sealing = delta.sealAsync(2);

		// a test hook observes the capture thread: it keeps the executor path
		assertThat(sealing.isDone()).isFalse();
		assertThat(executor.submitted).isPositive();
		executor.runAll();
		assertThat(hookRan).isTrue();
		SealedDirectDelta sealed = sealing.join();
		try {
			assertThat(sealed.pendingTable().rowCount()).isEqualTo(2);
		} finally {
			sealed.close();
		}
		assertThat(account.totalChargedBytes()).isZero();
	}
}
